					Body = body,
				})
				if ok and type(resp) == "table" and type(resp.Body) == "string" and resp.Body ~= "" then
					return resp.Body
				end
			end
		end
		
		local out
		pcall(function()
			local Http = game:GetService("HttpService")
			out = Http:PostAsync(url, body, Enum.HttpContentType.ApplicationJson)
		end)
		return out
	end

	
	
	
	
	
	
	local function leave_receipt(opts, decoded)
		local okg, g = pcall(function()
			return getgenv and getgenv()
		end)
		if not okg or type(g) ~= "table" then
			return
		end
		local at
		pcall(function()
			at = os.time()
		end)
		g.LUAVM_LICENSE_OK = {
			status = "VALID",
			key = opts.license_key or "",
			build_id = opts.build_id,
			tier = decoded.tier,
			expires_at = decoded.expires_at,
			expires_in_seconds = tonumber(decoded.expires_in_seconds),
			expires_in_days = tonumber(decoded.expires_in_days),
			at = at,
		}
	end

	
	
	local function loader(opts)
		local user_id, username = get_identity()
		local reqbody = JSON.encode({
			key = opts.license_key or "",
			hardware_id = get_hwid(),
			build_id = opts.build_id,
			user_id = user_id,
			username = username,
		})
		local resp = http_post(opts.endpoint, reqbody)
		if type(resp) ~= "string" or resp == "" then
			return nil, "no server response"
		end
		local decoded = JSON.decode(resp)
		if type(decoded) ~= "table" then
			return nil, "bad server response"
		end
		if decoded.status ~= "VALID" or type(decoded.unlock) ~= "string" or decoded.unlock == "" then
			return nil, "license " .. tostring(decoded.status or "rejected")
		end
		leave_receipt(opts, decoded)
		local key = hexdecode(decoded.unlock)
		if not key then
			return nil, "damaged server response"
		end
		local cipher = b64decode(opts.cipher_b64)
		if not cipher then
			return nil, "damaged payload"
		end
		local plain = keystream_xor(cipher, key)

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		local want = opts.payload_sha
		if type(want) ~= "string" or want == "" then
			return nil, "this build carries no payload digest"
		end
		if tohex(sha256(plain)) ~= want then
			return nil, "payload failed its integrity check"
		end
		return plain
	end

	return {
		load = loader,
		
		_crypto = {
			sha256 = sha256,
			keystream_xor = keystream_xor,
			b64decode = b64decode,
			hexdecode = hexdecode,
			tohex = tohex,
		},
	}
end

    end)()(JSON)

    local function resolve_license_key()
        
        
        
        local okg, g = pcall(function() return getgenv and getgenv() end)
        if okg and type(g) == "table" and g.LUAVM_LICENSE_KEY then
            return g.LUAVM_LICENSE_KEY
        end
        if _G and _G.LUAVM_LICENSE_KEY then
            return _G.LUAVM_LICENSE_KEY
        end
        if shared and shared.LUAVM_LICENSE_KEY then
            return shared.LUAVM_LICENSE_KEY
        end
        if typeof(rconsoleinput) == "function" then
            rconsoleprint("Enter license key: ")
            local ok, key = pcall(rconsoleinput)
            if ok and key and key ~= "" then
                return key
            end
        end
        return nil
    end

    local CIPHER = ""

    local ok, err = pcall(function()
        local payload, reason = FullLock.load({
            endpoint = "https://luavm-rvrse-license-production.up.railway.app/api/v1/licensing/validate",
            build_id = "4cb68bcd07880294",
            cipher_b64 = CIPHER,
            payload_sha = "4bd71b99b8ec7338aa90744056ceba5db920d14e4b40c599117fdd333bf35f56",
            license_key = resolve_license_key(),
        })
        if not payload then
            error(reason or "unlock failed", 0)
        end
        VM.load(payload, nil)
    end)

    if not ok then
        warn("Execution failed: " .. tostring(err))
    end
end)()
